<?php
require __DIR__.'/admin-navigation.php';
$sections=['pages'=>t('Pages'),'pages/layout'=>t('Page layout'),'posts'=>t('Posts'),'media'=>t('Library'),'media/trash'=>t('Media trash'),'categories'=>t('Categories'),'system'=>t('Site information'),'system/footer'=>t('Footer settings'),'tags'=>t('Tags'),'links'=>t('Links'),'menus'=>t('Menus'),'tabs'=>t('Mobile tabs'),'users'=>t('Users')];
$section=trim(substr(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH),strlen('/admin')),'/') ?: 'posts';
if(!isset($sections[$section])){http_response_code(404);$section='missing';}
$siteName=setting('site_name','Brainpress');
$statusFilter=in_array($_GET['status']??'', ['published','draft','trash'],true)?$_GET['status']:'';
$adminSearch=mb_substr(trim((string)($_GET['s']??'')),0,200);
$current=max(1,(int)($_GET['page']??1));$perPage=20;
$adminWhere=' WHERE 1=1';$adminParams=[];
if($statusFilter){$adminWhere.=' AND p.status=?';$adminParams[]=$statusFilter;}
if($adminSearch!==''){$adminWhere.=' AND p.title LIKE ?';$adminParams[]='%'.$adminSearch.'%';}
$adminTotal=(int)query('SELECT COUNT(*) FROM posts p'.$adminWhere,$adminParams)->fetchColumn();
$adminPages=max(1,(int)ceil($adminTotal/$perPage));$current=min($current,$adminPages);$adminOffset=($current-1)*$perPage;
$adminPosts=$section==='posts'&&!$editor?query('SELECT p.*,c.name AS category_name FROM posts p JOIN categories c ON c.id=p.category_id'.$adminWhere." ORDER BY p.updated_at DESC,p.id DESC LIMIT $perPage OFFSET $adminOffset",$adminParams)->fetchAll():[];
function menuRow(array $item,int $index): void { ?>
<div class="menu-item"><input type="hidden" name="menu_id[]" value="<?=e($item['id']??'')?>"><select name="parent[]" data-selected="<?=e($item['parent']??'')?>" aria-label="<?=e(t('Parent menu'))?>"><option value=""><?=e(t('Top level'))?></option></select><label class="menu-visible"><input type="checkbox" name="enabled[]" value="<?=$index?>" <?=($item['visible']??true)?'checked':''?>> <?=e(t('Show'))?></label><input name="label[]" aria-label="<?=e(t('Menu label'))?> <?=$index+1?>" maxlength="40" placeholder="<?=e(t('Label'))?>" value="<?=e($item['label']??'')?>"><input name="url[]" aria-label="<?=e(t('Menu URL'))?> <?=$index+1?>" placeholder="<?=e(t('/ or https://…'))?>" value="<?=e($item['url']??'')?>"><div class="menu-order"><button type="button" class="text-button" data-up aria-label="<?=e(t('Move up'))?>">↑</button><button type="button" class="text-button" data-down aria-label="<?=e(t('Move down'))?>">↓</button><button type="button" class="text-button" data-remove><?=e(t('Remove'))?></button></div><details class="submenu-content"><summary><?=e(t('Submenu text'))?></summary><p class="muted"><?=e(t('Add text below this second-level heading. Leave the URL empty for plain text.'))?></p><input type="hidden" name="content[]" value="<?=e(json_encode($item['content']??[],JSON_UNESCAPED_UNICODE))?>"><div class="submenu-content-rows"></div><button type="button" class="text-button" data-add-content><?=e(t('Add text'))?></button></details></div>
<?php }
